from collections import deque

def solve(n, edges, s, t):
    if s == t:
        return 0

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    # Bellman-Ford algorithm to find shortest path from s to t
    # since n is small (<= 100) and edges are <= 600, it's efficient
    dist = [float('inf')] * n
    dist[s] = 0

    # Relax edges up to n-1 times
    for i in range(n-1):
        for u in range(n):
            if dist[u] == float('inf'):
                continue
            for v, w in adj[u]:
                if dist[v] > dist[u] + w:
                    dist[v] = dist[u] + w

    # Check for negative weight cycles (but the problem says 0 <= w <= 100)
    # So no need for cycle check here as per problem constraints

    return dist[t] if dist[t] != float('inf') else -1
