def solve(n, edges, s, t):
    if s == t:
        return 0

    # Build adjacency list
    from collections import defaultdict
    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))

    # Bellman-Ford algorithm
    dist = [float('inf')] * n
    dist[s] = 0

    # Relax edges up to n-1 times
    for i in range(n - 1):
        updated = False
        for u in graph:
            for v, w in graph[u]:
