def solve(n, edges, s, t):
    if s == t:
        return 0

    from collections import defaultdict, deque

    # Build adjacency list
    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))

    # Bellman-Ford algorithm to find the shortest path from s to t
    # Since n <= 100, Bellman-Ford is acceptable

    # Initialize distance array
    dist = [float('inf')] * n
    dist[s] = 0

    # Relax edges up to n-1 times
    for i in range(n-1):
        updated = False
        for u in graph:
            for v, w in graph[u]:
                if dist[u] + w < dist[v]:
                    dist[v] = dist[u] + w
                    updated = True
        if not updated:
            break  # No more updates, can break early

    return dist[t] if dist[t] != float('inf') else -1
```

