def solve(n, edges, s, t):
    if s == t:
        return 0

    from collections import deque

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    # BFS with priority (Dijkstra's alternative using deque and priority)
    # Since we can't use Dijkstra's algorithm, we will use a modified Bellman-Ford approach
    # Bellman-Ford is O(VE) which is acceptable for n <= 100 and E <= 600

    # Initialize distance array
    dist = [float('inf')] * n
    dist[s] = 0

    # Relax edges up to n-1 times
    for _ in range(n - 1):
        updated = False
        for u in range(n):
            if dist[u] == float('inf'):
                continue
            for v, w in adj[u]:
                if dist[v] > dist[u] + w:
                    dist[v] = dist[u] + w
                    updated = True
        if not updated:
            break

    return dist[t] if dist[t] != float('inf') else -1
