def solve(n, edges, s, t):
    if s == t:
        return 0

    from collections import defaultdict
    import heapq

    # Build adjacency list
    adj = defaultdict(list)
    for u, v, w in edges:
        adj[u].append((v, w))

    # Dijkstra's algorithm implementation without using the standard one
    dist = [float('inf')] * n
    dist[s] = 0
    heap = [(0, s)]

    while heap:
        current_dist, u = heapq.heappop(heap)
        if u == t:
            return current_dist
        if current_dist > dist[u]:
            continue
        for v, w in adj[u]:
            if dist[v] > dist[u] + w:
                dist[v] = dist[u] + w
                heapq.heappush(heap, (dist[v], v))

    return -1
